    code: '() => {\n    const [date, setDate] = React.useState();\n    return (\n      <Table>\n        <TableHead>\n          <TableRow>\n            <HeaderCell>Navn</HeaderCell>\n            <HeaderCell>Dato</HeaderCell>\n          </TableRow>\n        </TableHead>\n        <TableBody>\n          <TableRow hover>\n            <EditableCell variant="negative" feedback="Navn mangler">\n              <TextField\n                aria-label="Navn"\n                append={\n                  <ValidationErrorFilledIcon\n                    inline\n                    color={colors.validation.lava}\n                    aria-hidden="true"\n                  />\n                }\n              ></TextField>\n            </EditableCell>\n            <EditableCell>\n              <DatePicker\n                aria-label="Dato"\n                selectedDate={date}\n                onChange={date => setDate(date)}\n              ></DatePicker>\n            </EditableCell>\n          </TableRow>\n          <TableRow hover>\n            <EditableCell outlined>\n              <TextField aria-label="Navn"></TextField>\n            </EditableCell>\n            <DataCell>Nordmann</DataCell>\n          </TableRow>\n          <TableRow>\n            <DataCell>Ola</DataCell>\n            <DataCell>Nordmann</DataCell>\n          </TableRow>\n        </TableBody>\n      </Table>\n    );\n  }',
