    code: "() => {\n    const [activeIndex, setActiveIndex] = React.useState(0);\n    const steps = ['Betaling', 'Kvittering', 'Billettering'];\n    return (\n      <>\n        <Label>Vanlig stepper</Label>\n        <Stepper steps={steps} activeIndex={1} />\n        <Label>Interaktiv stepper</Label>\n        <Stepper\n          steps={steps}\n          activeIndex={activeIndex}\n          onStepClick={setActiveIndex}\n          interactive\n        />\n        <div style={{ display: 'flex', justifyContent: 'space-between' }}>\n          <IconButton\n            onClick={() =>\n              setActiveIndex(activeIndex > 0 ? activeIndex - 1 : 0)\n            }\n          >\n            Tilbake\n          </IconButton>\n          <IconButton\n            onClick={() =>\n              setActiveIndex(activeIndex < 2 ? activeIndex + 1 : 2)\n            }\n          >\n            Frem\n          </IconButton>\n        </div>\n      </>\n    );\n  }",
