    group: 'Checkbox',
    name: 'Checkbox: <Fieldset>',
    code: '<Fieldset label="Hvilke type checkbox skal du velge?">\n  <Checkbox>Normal</Checkbox>\n  <Checkbox checked disabled>disabled</Checkbox>\n  <Checkbox checked readOnly>readOnly</Checkbox>\n</Fieldset>',
