    code: '<Fieldset name="ticket-type" label="Velg tilleggsprodukter:">\n    <div\n      style={{\n        display: \'flex\',\n        flexDirection: \'column\',\n        gap: \'0.5rem\',\n        width: \'20rem\',\n      }}\n    >\n      <CheckboxPanel title="Setereservasjon" value="seat" />\n      <CheckboxPanel title="Hund" value="dog" />\n      <CheckboxPanel title="Sykkel" value="flexi">\n        <Label as="span">Plass til sykkelen kan ikke garanteres</Label>\n      </CheckboxPanel>\n      <PrimaryButton>\n        Gå videre <ForwardIcon inline />\n      </PrimaryButton>\n    </div>\n  </Fieldset>',
